using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI Setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();

var chatClient = sp.GetRequiredService<IChatClient>();
var logger = sp.GetRequiredService<ILogger<Program>>();

// --- Tools ---
var tools = new ResearchTools();

// --- Agent ---
var agent = new ChatClientAgent(chatClient)
{
    Name = "ResearchAgent",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use the WebSearch tool multiple times with different queries to gather information.
        2. Use the AddNote tool to record key findings as you go.
        3. After gathering enough information, use GetNotes to review your notes.
        4. Provide a well-structured summary with sections and citations.
        Be thorough — search at least 3 different angles of the topic.
        """,
    Tools = [AIFunctionFactory.Create(tools.WebSearch),
             AIFunctionFactory.Create(tools.AddNote),
             AIFunctionFactory.Create(tools.GetNotes)],
};

// --- Run ---
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions { MaximumIterations = 15 };

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// --- Tool Definitions ---
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information. Returns a list of result snippets.")]
    public async Task<string> WebSearch(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Uses DuckDuckGo HTML search (no API key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var snippets = ParseSearchResults(html);

            if (snippets.Count == 0)
            {
                return $"No results found for \"{query}\".";
            }

            var results = snippets
                .Take(5)
                .Select((s, i) => $"[{i + 1}] {s}")
                .ToList();

            return $"Search results for \"{query}\":\n" + string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    [Description("Add a research note. Use this to record key findings during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} added.");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var formatted = _notes
            .Select((n, i) => $"Note #{i + 1}: {n}")
            .ToList();

        Console.WriteLine($"  📋 Returning {_notes.Count} note(s).");
        return string.Join("\n\n", formatted);
    }

    private static List<string> ParseSearchResults(string html)
    {
        var snippets = new List<string>();

        // Extract result snippets from DuckDuckGo HTML response
        const string snippetMarker = "class=\"result__snippet\"";
        var index = 0;

        while ((index = html.IndexOf(snippetMarker, index, StringComparison.Ordinal)) != -1)
        {
            var tagClose = html.IndexOf('>', index);
            if (tagClose == -1) break;

            var end = html.IndexOf("</", tagClose, StringComparison.Ordinal);
            if (end == -1) break;

            var text = html[(tagClose + 1)..end];
            text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", "");
            text = WebUtility.HtmlDecode(text).Trim();

            if (!string.IsNullOrWhiteSpace(text))
            {
                snippets.Add(text);
            }

            index = end;
        }

        return snippets;
    }
}

