             .Select((n, i) => $"Note #{i + 1}: {n}")
             .ToList();

         Console.WriteLine($"  📋 Returning {_notes.Count} note(s).");
         return string.Join("\n\n", formatted);
     }

     private static List<string> ParseSearchResults(string html)
     {
         var snippets = new List<string>();

         // Extract result snippets from DuckDuckGo HTML response
         const string snippetMarker = "class=\"result__snippet\"";
         var index = 0;

         while ((index = html.IndexOf(snippetMarker, index, StringComparison.Ordinal)) != -1)
         {
             var tagClose = html.IndexOf('>', index);
             if (tagClose == -1) break;

             var end = html.IndexOf("</", tagClose, StringComparison.Ordinal);
             if (end == -1) break;

             var text = html[(tagClose + 1)..end];
             text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", "");
             text = WebUtility.HtmlDecode(text).Trim();

             if (!string.IsNullOrWhiteSpace(text))
             {
                 snippets.Add(text);
             }

             index = end;
         }

         return snippets;
     }
 }

